import json
from pathlib import Path
import tempfile
import unittest

import numpy as np

from ads1800_app.modal import ModalConfig, ModalSession
from ads1800_app.modal_post import (ModalData, PostSettings, prepare_data, fit_modes,
                                   suggest_modes, export_results)


def analytic_data(alpha=0, noise=0):
    """Independent continuous mechanical model, not generated by the fitter basis."""
    f = np.arange(0, 250.125, .125)
    s = alpha+2j*np.pi*f
    residues = np.array([[.3, .1], [.1, -.2], [-.2, .15]])
    h = []
    rng = np.random.default_rng(83)
    for coeffs in residues:
        response = np.zeros(len(f), complex)
        for residue, fn, zeta in zip(coeffs, [40, 85], [.012, .025]):
            w = 2*np.pi*fn
            response += residue*s*s/(s*s+2*zeta*w*s+w*w)
        response += .01+1e-8*s*s
        response += noise*(rng.normal(size=len(f))+1j*rng.normal(size=len(f)))
        h.append(response)
    return ModalData(f, np.asarray(h), np.full((3, len(f)), .99),
                     ['P1', 'P2', 'P3'], [3, 3, 3], alpha, [], [])


def raw_session(folder):
    c = ModalConfig(sample_rate=2000, bandpass_enabled=False, duration=4, pretrigger=.05, force_width=.02,
                    response_window='Hann')
    session = ModalSession(Path(folder)/'run', c)
    f = np.fft.rfftfreq(c.n, 1/c.sample_rate)
    s = 2j*np.pi*f
    force = np.zeros(c.n)
    force[c.pre] = 100
    for point, residues in zip(['P1', 'P2', 'P3'], [[.3, .1], [.1, -.2], [-.2, .15]]):
        response = np.zeros(len(f), complex)
        for r, fn, zeta in zip(residues, [40, 85], [.012, .025]):
            w = 2*np.pi*fn
            response += r*s*s/(s*s+2*zeta*w*s+w*w)
        acceleration = np.fft.irfft(np.fft.rfft(force)*response, n=c.n)
        data = np.column_stack([np.arange(c.n)/c.sample_rate, force, acceleration])
        for _ in range(2):
            record, _ = session.capture(point, data)
            session.review(record, True)
    return session


class PostTests(unittest.TestCase):
    def settings(self):
        return PostSettings(fmin=20, fmax=115, max_modes=2)

    def test_shared_modes_frequency_damping_signed_shapes_and_resynthesis(self):
        data = analytic_data(noise=.001)
        settings = self.settings()
        candidates = suggest_modes(data, settings)
        self.assertEqual(len(candidates), 2)
        result = fit_modes(data, settings)
        np.testing.assert_allclose([m['frequency_hz'] for m in result['modes']], [40, 85], atol=.02)
        np.testing.assert_allclose([m['damping_ratio'] for m in result['modes']], [.012, .025], rtol=.01)
        shapes = [list(m['shape'].values()) for m in result['modes']]
        np.testing.assert_allclose(shapes, [[1, 1/3, -2/3], [-.5, 1, -.75]], atol=.003)
        self.assertLess(max(result['relative_fit_error'].values()), .005)

    def test_exponential_is_accounted_for_in_physical_damping(self):
        data = analytic_data(alpha=4)
        result = fit_modes(data, self.settings(), [39, 86])
        np.testing.assert_allclose([m['frequency_hz'] for m in result['modes']], [40, 85], atol=1e-5)
        np.testing.assert_allclose([m['damping_ratio'] for m in result['modes']], [.012, .025], atol=1e-7)

    def test_close_modes_with_manual_candidates(self):
        data = analytic_data()
        s = 2j*np.pi*data.frequency
        for i, residues in enumerate([[.3, .1], [.1, -.2], [-.2, .15]]):
            data.frfs[i] = sum(r*s*s/(s*s+2*.01*2*np.pi*f*s+(2*np.pi*f)**2)
                               for r, f in zip(residues, [40, 43]))
        result = fit_modes(data, PostSettings(fmin=30, fmax=55), [39.8, 43.2])
        np.testing.assert_allclose([m['frequency_hz'] for m in result['modes']], [40, 43], atol=.001)

    def test_rebuild_original_signals_ignores_rejected_and_original_hann(self):
        with tempfile.TemporaryDirectory() as folder:
            session = raw_session(folder)
            settings = self.settings()
            data = prepare_data(session, settings)
            result = fit_modes(data, settings, [40, 85])
            np.testing.assert_allclose([m['frequency_hz'] for m in result['modes']], [40, 85], atol=.08)
            np.testing.assert_allclose([m['damping_ratio'] for m in result['modes']], [.012, .025], atol=.002)
            # Rejecting a repeat excludes the point at the default minimum of two.
            session.review(session.records[0], False)
            prepared = prepare_data(session, settings)
            self.assertEqual(prepared.point_ids, ['P2', 'P3'])
            self.assertNotIn(session.records[0]['file'], [r['file'] for r in prepared.source_records])
            directory = Path(folder)/'results'
            export_results(result, directory)
            saved = json.loads((directory/'modos.json').read_text(encoding='utf-8'))
            self.assertEqual(len(saved['modes']), 2)
            self.assertTrue((directory/'formas_modais.csv').exists())
            with np.load(directory/'frfs_ajustadas.npz') as spectra:
                np.testing.assert_equal(spectra['measured'], result['measured'])

    def test_missing_coherence_zero_data_and_invalid_seeds(self):
        data = analytic_data()
        data.coherence[:] = .2
        with self.assertRaises(ValueError):
            fit_modes(data, self.settings(), [40, 85])
        data = analytic_data()
        for seeds in [[40, 40], [float('nan')], [5], []]:
            with self.assertRaises(ValueError):
                fit_modes(data, self.settings(), seeds)
        data.frfs[:] = 0
        self.assertEqual(suggest_modes(data, self.settings()), [])
        with self.assertRaises(ValueError):
            fit_modes(data, self.settings())

    def test_underresolved_damping_is_flagged(self):
        data = analytic_data()
        data.frequency = data.frequency[::8]
        data.frfs = data.frfs[:, ::8]
        data.coherence = data.coherence[:, ::8]
        result = fit_modes(data, self.settings(), [40, 85])
        self.assertTrue(any('bins' in note for note in result['modes'][0]['warnings']))
